    }
}

static int* parseCIntArray(char* s, int* outSize) {
    *outSize = 0;
    if (!s) return NULL;
    char* p = strchr(s, '[');
    if (!p) return NULL;
    p++;
    int cap = 16, sz = 0;
    int* arr = (int*)malloc(cap * sizeof(int));
    while (*p && *p != ']') {
